10		"github.com/entireio/auth-go/tokens"
11		"github.com/entireio/cli/cmd/entire/cli/api"
12		"github.com/entireio/cli/internal/entireclient/contexts"
13		"github.com/entireio/cli/internal/entireclient/tokenstore"
14	)
15	
16	// defaultContextTokenTTL is the encoded keychain expiry used when a login
17	// token carries no usable exp claim (e.g. an opaque, non-JWT bearer). The
18	// server is the real authority on validity; this only governs when local
19	// readers consider the token stale, and we hold no refresh token to act on
20	// it, so a conservative non-zero value is enough to keep the entry usable.
21	const defaultContextTokenTTL = time.Hour
22	
23	// RecordLoginContext records a freshly obtained login token in the
24	// shared contexts.json credential model: it derives the issuer (core
25	// URL), handle, and expiry from the token's own claims, stores the token
26	// in the OS keyring under the entire-core:<issuer> service scheme entiredb
27	// uses, and writes (or updates) the matching context.
28	//
29	// Contexts are keyed by identity (core URL + handle): re-logging into the
30	// same identity updates its context in place, while a second identity on
31	// the same core gets its own context (named handle@host) instead of
32	// clobbering the first.
33	//
34	// activate controls current_context: login passes true (the just-completed
35	// login becomes active, kubectl use-context style); read-time migration
36	// passes false so it never silently switches the user's active account —
37	// it still sets current_context when none exists yet.
38	//
39	// This is the contexts.json half of login's dual-write: the legacy
40	// entire-cli/<authBaseURL> keyring entry is still written by the caller so
41	// the control-plane readers keep working untouched during the transition.
42	// A login recorded here is visible to entiredb's CLIs (and the in-CLI git
43	// remote helper) because they share this file and keychain layout.
44	//
45	// Returns the context name on success. Errors are returned (not swallowed)
46	// so the caller can warn; login still succeeds on the legacy entry.
47	func RecordLoginContext(rawToken string, activate bool) (string, error) {
48		claims, err := tokens.ParseClaims(rawToken)
49		if err != nil {
50			return "", fmt.Errorf("parse login token claims: %w", err)
51		}
52		coreURL := claims.Issuer
53		if coreURL == "" {
54			return "", errors.New("login token has no iss claim; cannot derive core URL for a context")
55		}
56		handle := claims.Handle
57		if handle == "" {
58			handle = claims.Subject
59		}
60		if handle == "" {
61			return "", errors.New("login token has no handle/sub claim; cannot key the keychain slot")
62		}
63	
64		keychainService := tokenstore.CoreKeyringService(coreURL)
65	
66		expiresIn := int64(defaultContextTokenTTL.Seconds())
67		if !claims.ExpiresAt.IsZero() {
68			if secs := int64(time.Until(claims.ExpiresAt).Seconds()); secs > 0 {
69				expiresIn = secs
70			}
71		}
72	
73		encoded := tokenstore.EncodeTokenWithExpiration(rawToken, expiresIn)
74		if err := tokenstore.Set(keychainService, handle, encoded); err != nil {
75			return "", fmt.Errorf("store login token in keyring: %w", err)
76		}
77	
78		var name string
79		cfgDir := contexts.DefaultConfigDir()
80		if modErr := contexts.Modify(cfgDir, func(f *contexts.File) (bool, error) {
81			name = pickContextName(f, coreURL, handle)
82			f.Upsert(&contexts.Context{
83				Name:            name,
84				CoreURL:         coreURL,
85				Handle:          handle,
86				KeychainService: keychainService,
87			})
88			if activate || f.CurrentContext == "" {
89				f.CurrentContext = name
90			}
91			return true, nil
92		}); modErr != nil {
93			return "", fmt.Errorf("write context: %w", modErr)
94		}
95	
96		return name, nil
97	}
98	
99	// pickContextName chooses the contexts.json name for an (coreURL, handle)
100	// identity within f. An existing context for the same identity keeps its
101	// name (re-login updates in place). A fresh identity prefers the bare core
102	// host; if a *different* identity already holds that name, it's qualified
103	// with the handle (handle@host) so the two don't collide — and, in the
104	// pathological case that's taken too, a numeric suffix guarantees
105	// uniqueness.
106	func pickContextName(f *contexts.File, coreURL, handle string) string {
107		for _, c := range f.Contexts {
108			if sameIssuer(c.CoreURL, coreURL) && c.Handle == handle {
109				return c.Name
110			}
111		}
112		host := contextNameForCoreURL(coreURL)
113		if f.Find(host) == nil {
114			return host
115		}
116		qualified := handle + "@" + host
117		if f.Find(qualified) == nil {
118			return qualified
119		}
120		for i := 2; ; i++ {
121			candidate := fmt.Sprintf("%s-%d", qualified, i)
122			if f.Find(candidate) == nil {
123				return candidate
124			}
125		}
126	}
127	
128	// sameIssuer compares two core URLs ignoring a trailing slash.
129	func sameIssuer(a, b string) bool {
130		return strings.TrimRight(a, "/") == strings.TrimRight(b, "/")
131	}
132	
133	// MigrateLegacyLoginContext bridges users who logged in before the
134	// contexts.json dual-write existed: if the legacy entire-cli/<authBaseURL>
135	// keyring entry holds a usable JWT and no context yet covers its issuer,
136	// it records an equivalent context (and keychain entry under the shared
137	// scheme) so the git remote helper can authenticate without a re-login.
138	//
139	// Returns (true, nil) when it created a context. No-ops — returning
140	// (false, nil) — when there's no legacy token, the token is opaque
141	// (no derivable issuer), or a context for that issuer already exists.
142	// Idempotent: safe to call on every helper invocation.
143	func MigrateLegacyLoginContext() (migrated bool, err error) {
144		legacy, err := NewStore().GetToken(api.AuthBaseURL())
145		if err != nil {
146			return false, fmt.Errorf("read legacy login token: %w", err)
147		}
148		if legacy == "" {
149			return false, nil
150		}
151		claims, parseErr := tokens.ParseClaims(legacy)
152		if parseErr != nil || claims.Issuer == "" {
153			// Opaque/unsigned legacy token — can't derive a context from it.
154			return false, nil //nolint:nilerr // absence of a JWT issuer is not an error here
155		}
156		handle := claims.Handle
157		if handle == "" {
158			handle = claims.Subject
159		}
160		f, err := contexts.Load(contexts.DefaultConfigDir())
161		if err != nil {
162			return false, fmt.Errorf("load contexts: %w", err)
163		}
164		// Skip only when this exact identity is already represented. Keying on
165		// issuer alone would skip a legacy bob@core just because alice@core (e.g.
166		// from another CLI) already exists, leaving Bob without a context.
167		for _, c := range f.Contexts {
168			if sameIssuer(c.CoreURL, claims.Issuer) && c.Handle == handle {
169				return false, nil
170			}
171		}
172		// activate=false: migrating an old login (e.g. on first `git clone`) must
173		// not silently switch the user's active context. RecordLoginContext still
174		// sets current_context when none exists yet.
175		if _, err := RecordLoginContext(legacy, false); err != nil {
176			return false, err
177		}
178		return true, nil
179	}
180	
181	// LoginTokenForContext returns the login JWT stored for c, read from the
182	// OS keyring slot the context points at. The encoded expiry is stripped;
183	// the server is the authority on validity and the device-flow login holds
184	// no refresh token, so an expired token surfaces as a 401 the caller can
185	// translate into a re-login hint.
186	func LoginTokenForContext(c *contexts.Context) (string, error) {
187		if c == nil {
188			return "", errors.New("nil context")
189		}
190		if c.KeychainService == "" || c.Handle == "" {
191			return "", fmt.Errorf("context %q has no keychain slot", c.Name)
192		}
193		encoded, err := tokenstore.Get(c.KeychainService, c.Handle)
194		if err != nil {
195			return "", fmt.Errorf("read token for context %q: %w", c.Name, err)
196		}
197		if encoded == "" {
198			return "", fmt.Errorf("no token stored for context %q (run `entire login`)", c.Name)
199		}
200		token, _ := tokenstore.DecodeTokenWithExpiration(encoded)
201		return token, nil
202	}
203	
204	// contextNameForCoreURL derives a stable, human-readable context name
205	// from the issuer URL — its host, matching entiredb's default of naming a
206	// context after the core it authenticates against. Falls back to the raw
207	// URL when it can't be parsed.
208	func contextNameForCoreURL(coreURL string) string {
209		if u, err := url.Parse(coreURL); err == nil && u.Host != "" {
210			return u.Host
211		}
212		return coreURL
213	}
