199	// is appended — unlike intermediate have-batch rounds, the probe
200	// response IS the round terminator (its trailing flush) that git is
201	// waiting for, and appending NAK would confuse the client into
202	// thinking negotiation has already happened.
203	func postShallowProbe(ctx context.Context, t Transport, stdout io.Writer, wantsBuf *bytes.Buffer) error {
204		body, err := gitproto.AppendAgentToUploadPackRequest(append([]byte(nil), wantsBuf.Bytes()...), Agent)
205		if err != nil {
