115		// surface — we only have an access-token string at this point;
116		// the deviceflow client doesn't return a TokenSet here.
117		if err := store.SaveToken(client.BaseURL(), token); err != nil {
118			return fmt.Errorf("save auth token: %w", err)
119		}
