122		// remote helper (and entiredb's CLIs) can authenticate against any
123		// entitled cluster from this login. Best-effort: the legacy entry
124		// above remains the control-plane source of truth, so a failure here
125		// must not fail the login — warn and continue.
126		if _, err := auth.RecordLoginContext(token, true); err != nil {
