134	// validateReceivedToken runs minimum-trust checks on the access token
135	// the AS handed us before we persist it. The server is the authority
136	// on signature/exp; this is defense in depth aimed at catching gross
137	// misbehaviour by a compromised or misconfigured AS (e.g. handing back
138	// a token from a different issuer than the one we asked, or one whose
139	// claims are already-expired).
140	//
141	// Opaque (non-JWT) tokens are permitted — the AS may not issue JWTs at
142	// all. Only when we can parse the token as a JWT do we cross-check the
143	// claims. Unsigned (alg:none) JWTs are always rejected via
144	// tokens.ErrUnsignedJWT; every other parse failure (3-segment-but-not-
145	// base64, payload-not-JSON, header-not-JSON, etc.) is treated as opaque
146	// and accepted, so a server issuing dot-bearing non-JWT bearer tokens
147	// can still log in.
148	func validateReceivedToken(rawToken, issuerURL string, now time.Time) error {
149		claims, err := tokens.ParseClaims(rawToken)
150		if errors.Is(err, tokens.ErrUnsignedJWT) {
151			return err //nolint:wrapcheck // sentinel surfaces verbatim for caller's errors.Is
152		}
153		if err != nil {
154			return nil //nolint:nilerr // any parse failure other than alg:none means the token isn't a JWT — opaque tokens are valid
155		}
156	
157		// iss check: the token must claim to come from the issuer we sent
158		// the device-code request to. A mismatch means either the AS is
159		// misconfigured or someone's playing games.
160		if issErr := issMatches(claims.Issuer, issuerURL); issErr != nil {
161			return issErr
162		}
163	
164		// exp sanity: a token that's already expired before we even store
165		// it is a smell. Don't reject if exp is unset (some servers omit).
166		if !claims.ExpiresAt.IsZero() && !now.Before(claims.ExpiresAt) {
167			return fmt.Errorf("token already expired (exp=%s, now=%s)",
168				claims.ExpiresAt.Format(time.RFC3339), now.Format(time.RFC3339))
169		}
170	
171		return nil
172	}
