174	// issMatches reports whether claimed equals expected after stripping path/
175	// query/fragment via api.OriginOnly, so "https://issuer/" and "https://issuer"
176	// match. Returns nil on match or when the iss claim is empty (some servers
177	// omit it — the server still does the real check on every request).
178	func issMatches(claimed, expected string) error {
179		if claimed == "" {
180			return nil
181		}
182		normClaimed := api.OriginOnly(claimed)
183		normExpected := api.OriginOnly(expected)
184		if normClaimed != normExpected {
185			return fmt.Errorf("iss mismatch: token claims %q, expected %q", normClaimed, normExpected)
186		}
187		return nil
188	}
