208	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
209		expiry := time.Duration(expiresIn) * time.Second
210		if expiry <= 0 || expiry > maxExpiresIn {
211			expiry = maxExpiresIn
212		}
213		deadline := time.Now().Add(expiry)
214		pollInterval := interval
215		if pollInterval <= 0 {
216			pollInterval = fallbackDeviceAuthPollInterval
217		}
218	
219		consecutiveErrors := 0
220	
221		for {
222			if time.Now().After(deadline) {
223				return "", errors.New("device authorization expired")
224			}
225	
226			result, err := poller.PollDeviceAuth(ctx, deviceCode)
227			if err != nil {
228				consecutiveErrors++
229				if consecutiveErrors >= maxTransientErrors {
230					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
231				}
232				// Transient error — wait and retry.
233				select {
234				case <-ctx.Done():
235					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
236				case <-time.After(pollInterval):
237				}
238				continue
239			}
240			consecutiveErrors = 0
241	
242			switch result.Error {
243			case "":
244				if result.AccessToken == "" {
245					return "", errors.New("device authorization completed without a token")
246				}
247				return result.AccessToken, nil
248			case "authorization_pending":
249				// no-op, will sleep and retry below
250			case "slow_down":
251				pollInterval += slowDownBackoff
252				if pollInterval > maxPollInterval {
253					pollInterval = maxPollInterval
254				}
255			case "access_denied":
256				return "", errors.New("device authorization denied")
257			case "expired_token":
258				return "", errors.New("device authorization expired")
259			default:
260				if result.ErrorDescription != "" {
261					return "", fmt.Errorf("device authorization failed: %s: %s", result.Error, result.ErrorDescription)
262				}
263				return "", fmt.Errorf("device authorization failed: %s", result.Error)
264			}
265	
266			select {
267			case <-ctx.Done():
268				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
269			case <-time.After(pollInterval):
270			}
271		}
272	}
