274	// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
275	// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
276	// Returns ctx.Err() if the context is cancelled before the user presses Enter.
277	func waitForEnter(ctx context.Context) error {
278		tty, err := os.Open("/dev/tty")
279		if err != nil {
280			return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
281		}
282	
283		done := make(chan error, 1)
284		go func() {
285			reader := bufio.NewReader(tty)
286			_, err := reader.ReadString('\n')
287			done <- err
288		}()
289	
290		select {
291		case <-ctx.Done():
292			// Close tty to unblock the reading goroutine.
293			_ = tty.Close()
294			return fmt.Errorf("interrupted: %w", ctx.Err())
295		case <-done:
296			_ = tty.Close()
297			return nil
298		}
299	}
