301	func openBrowser(ctx context.Context, browserURL string) error {
302		u, err := url.Parse(browserURL)
303		if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
304			return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
305		}
306	
307		var command string
308		var args []string
309	
