18	)
19	
20	// authTokenLister lists API tokens for the authenticated user. The
21	// implementation resolves its own data-API bearer via
22	// auth.TokenForResource (RFC 8693 exchange in split-host setups, same-
23	// host shortcut otherwise); callers don't pass a bearer through, which
24	// removes the temptation to forward the wrong-audience keyring token.
25	type authTokenLister func(ctx context.Context) ([]api.Token, error)
26	
27	// authTokenRevoker revokes a single API token by id. Same bearer-
28	// resolution contract as authTokenLister.
29	type authTokenRevoker func(ctx context.Context, id string) error
30	
31	// User-visible placeholder strings. Promoted to constants so tests and
32	// production share a single source of truth.
33	const (
34		placeholderDash = "-"
35		lastUsedNever   = "never"
36		lastUsedJustNow = "just now"
37	)
38	
39	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
40	// command that sends a bearer token over the network (login, logout,
41	// auth status/list/revoke) must call this so credentials don't leak over
42	// plaintext HTTP without explicit opt-in.
43	//
44	// Both the auth and data API origins are checked: the bearer travels to the
45	// auth host for login + auth-token management, and to the data host for
46	// search/activity/dispatch/etc. When both origins resolve to the same host
47	// (e.g. an explicitly collapsed single-host deployment) the redundant second
48	// parse is skipped.
49	//
50	// When the opt-in flag is set, the tokenmanager's matching HTTP guard is
51	// also relaxed via auth.EnableInsecureHTTP — otherwise an STS exchange
52	// against a private-network http:// auth host would fail at the
53	// tokenmanager layer even though the per-command TLS check was waived.
54	func requireSecureBaseURL(insecureHTTPAuth bool) error {
55		if insecureHTTPAuth {
56			auth.EnableInsecureHTTP()
57			return nil
58		}
59		dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
60		if err := api.RequireSecureURL(dataURL); err != nil {
61			return fmt.Errorf("base URL check: %w", err)
62		}
63		if authURL == dataURL {
64			return nil
65		}
66		if err := api.RequireSecureURL(authURL); err != nil {
67			return fmt.Errorf("auth base URL check: %w", err)
68		}
69		return nil
70	}
71	
72	// newAPITokensClient builds an api.Client for the auth-token management
73	// endpoints (list / revoke / current). API tokens live on the data API
74	// regardless of split-host config — the auth host (entire-core in v2)
75	// mints OAuth tokens but doesn't host application API token management
76	// endpoints — so this targets api.BaseURL().
77	//
78	// The supplied token must already be scoped for api.BaseURL(). Callers
79	// must obtain it via resolveDataAPIToken (or auth.TokenForResource
80	// directly) rather than handing through the raw keyring entry — the
81	// keyring stores the auth-host-issued core token, which the data API
82	// rejects in split-host setups.
83	func newAPITokensClient(token string) *api.Client {
84		return api.NewClientWithBaseURL(token, api.BaseURL()).
85			WithAuthTokensPath(auth.CurrentProvider().AuthTokensPath)
86	}
87	
88	// resolveDataAPIToken returns a bearer scoped for the data API. In
89	// split-host setups this triggers an RFC 8693 exchange against the
90	// auth host's STS endpoint; in single-host setups the tokenmanager
91	// hits the same-host shortcut and returns the core token unchanged.
92	// Centralised so the audience-mismatch bug that motivated this fix
93	// can't be reintroduced piecemeal at individual call sites.
94	func resolveDataAPIToken(ctx context.Context) (string, error) {
95		token, err := auth.TokenForResource(ctx, api.OriginOnly(api.BaseURL()))
96		if err != nil {
97			return "", fmt.Errorf("resolve API token: %w", err)
98		}
99		return token, nil
100	}
101	
102	// isKeychainTokenRejected reports whether err indicates the stored
103	// keyring token can't authenticate against the data API. Three failure
104	// modes collapse into this single "the user must re-login" branch:
105	//
106	//   - data API returned 401 (single-host, or after a successful STS
107	//     exchange whose result the data API then rejected),
108	//   - tokenmanager's preflight rejected an expired core token JWT
109	//     (surfacing as auth.ErrNotLoggedIn even though the keyring entry
110	//     is still present),
111	//   - the STS endpoint rejected the core token during exchange in a
112	//     split-host setup. auth-go's sts package returns the response as
113	//     "token exchange: status 4xx: <code>[: <desc>]" with no typed
114	//     sentinel exposed, so detection has to be by prefix. The "status
115	//     4" anchor catches the entire 4xx range — every 4xx from STS is
116	//     a credential problem, none are retryable without user action.
117	//
118	// Other shapes (network errors, malformed STS response, manager
119	// construction failures) deliberately don't match — the user sees the
120	// real diagnostic instead of a misleading "re-login" hint.
121	func isKeychainTokenRejected(err error) bool {
122		if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
123			return true
124		}
125		if errors.Is(err, auth.ErrNotLoggedIn) {
126			return true
127		}
128		return strings.Contains(err.Error(), "token exchange: status 4")
129	}
130	
131	// addInsecureHTTPAuthFlag attaches the hidden --insecure-http-auth flag used
132	// by every authenticated command for local development.
133	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
134		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
135		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
136			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
137		}
138	}
139	
140	func newAuthCmd() *cobra.Command {
141		cmd := &cobra.Command{
142			Use:   "auth",
143			Short: "Manage authentication and API tokens",
144			Long:  "Authentication subcommands. Includes login, logout, status, listing tokens, and revoking tokens.",
145			RunE: func(cmd *cobra.Command, _ []string) error {
146				return cmd.Help()
147			},
148		}
149	
150		cmd.AddCommand(newLoginCmd())
151		cmd.AddCommand(newLogoutCmd())
152		cmd.AddCommand(newAuthStatusCmd())
153		cmd.AddCommand(newAuthListCmd())
154		cmd.AddCommand(newAuthRevokeCmd())
155		cmd.AddCommand(newAuthContextsCmd())
156		cmd.AddCommand(newAuthUseCmd())
157		return cmd
158	}
159	
160	// --- status -----------------------------------------------------------------
161	
162	func newAuthStatusCmd() *cobra.Command {
163		var insecureHTTPAuth bool
164		cmd := &cobra.Command{
165			Use:   "status",
166			Short: "Show authentication status",
167			RunE: func(cmd *cobra.Command, _ []string) error {
168				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
169					return err
170				}
171				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(),
172					auth.NewContextStore(), defaultListTokens, api.AuthBaseURL())
173			},
174		}
175		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
176		return cmd
177	}
178	
179	func defaultListTokens(ctx context.Context) ([]api.Token, error) {
180		token, err := resolveDataAPIToken(ctx)
181		if err != nil {
182			return nil, err
183		}
184		return newAPITokensClient(token).ListTokens(ctx) //nolint:wrapcheck // ListTokens already wraps with action context
185	}
186	
187	func runAuthStatus(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string) error {
188		token, err := store.GetToken(baseURL)
189		if err != nil {
190			return fmt.Errorf("read keychain: %w", err)
191		}
192		if token == "" {
193			fmt.Fprintf(w, "Not logged in to %s\n", baseURL)
194			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
195			return nil
196		}
197	
198		tokens, err := list(ctx)
199		if err != nil {
200			if isKeychainTokenRejected(err) {
201				fmt.Fprintf(w, "Token in keychain for %s is no longer valid.\n", baseURL)
202				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
203				return nil
204			}
205			return fmt.Errorf("validate token: %w", err)
206		}
207	
208		fmt.Fprintf(w, "Logged in to %s\n", baseURL)
209		fmt.Fprintln(w, "  Token: stored in OS keychain")
210		fmt.Fprintf(w, "  Active tokens on this account: %d\n", len(tokens))
211		return nil
212	}
213	
214	// --- list -------------------------------------------------------------------
215	
216	func newAuthListCmd() *cobra.Command {
217		var jsonOut bool
218		var insecureHTTPAuth bool
219		cmd := &cobra.Command{
220			Use:   "list",
221			Short: "List active API tokens for the authenticated user",
222			RunE: func(cmd *cobra.Command, _ []string) error {
223				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
224					return err
225				}
226				return runAuthList(cmd.Context(), cmd.OutOrStdout(),
227					auth.NewContextStore(), defaultListTokens, api.AuthBaseURL(), jsonOut)
228			},
229		}
230		cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
231		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
232		return cmd
233	}
234	
235	func runAuthList(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string, jsonOut bool) error {
236		token, err := store.GetToken(baseURL)
237		if err != nil {
238			return fmt.Errorf("read keychain: %w", err)
239		}
240		if token == "" {
241			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
242		}
243	
244		tokens, err := list(ctx)
245		if err != nil {
246			return err
247		}
248	
249		if jsonOut {
250			enc := json.NewEncoder(w)
251			enc.SetIndent("", "  ")
252			if err := enc.Encode(tokens); err != nil {
253				return fmt.Errorf("encode JSON: %w", err)
254			}
255			return nil
256		}
257	
258		if len(tokens) == 0 {
259			fmt.Fprintln(w, "No active tokens.")
260			return nil
261		}
262	
263		// Deterministic order: most recently used first, then most recently
264		// created, then by id as a final tie-breaker so the output is fully
265		// specified regardless of the server's response order.
266		sort.Slice(tokens, func(i, j int) bool {
267			li := lastUsedSortKey(tokens[i])
268			lj := lastUsedSortKey(tokens[j])
269			if li != lj {
270				return li > lj
271			}
272			if tokens[i].CreatedAt != tokens[j].CreatedAt {
273				return tokens[i].CreatedAt > tokens[j].CreatedAt
274			}
275			return tokens[i].ID < tokens[j].ID
276		})
277	
278		sty := newAuthListStyles(w)
279		renderAuthListTable(w, sty, tokens, time.Now())
280		return nil
281	}
282	
283	// authListStyles holds the lipgloss styles for `entire auth list`. Mirrors the
284	// approach in activity_render.go: keep style construction tied to color
285	// detection, and render plain text when color is disabled.
286	type authListStyles struct {
287		colorEnabled bool
288	
289		header  lipgloss.Style // bold + dim, used for column headers
290		id      lipgloss.Style // yellow accent
291		name    lipgloss.Style // bold
292		value   lipgloss.Style // default fg for scope/dates (no color)
293		dim     lipgloss.Style // "never", "-"
294		warning lipgloss.Style // expires-soon
295		expired lipgloss.Style // already expired
296	}
297	
298	func newAuthListStyles(w io.Writer) authListStyles {
299		useColor := shouldUseColor(w)
300		s := authListStyles{colorEnabled: useColor}
301		if !useColor {
302			return s
303		}
304		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
305		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
306		s.name = lipgloss.NewStyle().Bold(true)
307		s.value = lipgloss.NewStyle() // default fg
308		s.dim = lipgloss.NewStyle().Faint(true)
309		s.warning = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
310		s.expired = lipgloss.NewStyle().Foreground(lipgloss.Color("1")) // red
311		return s
312	}
313	
314	func (s authListStyles) render(style lipgloss.Style, text string) string {
315		if !s.colorEnabled {
316			return text
317		}
318		return style.Render(text)
319	}
320	
321	// renderAuthListTable prints a styled, column-aligned table of tokens. Column
322	// padding is computed via lipgloss.Width — it strips ANSI escapes, so a styled
323	// cell's visible width matches its plain text. tabwriter can't be used here
324	// once cells contain ANSI codes.
325	func renderAuthListTable(w io.Writer, sty authListStyles, tokens []api.Token, now time.Time) {
326		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
327		header := make([]string, len(headerCells))
328		for i, h := range headerCells {
329			header[i] = sty.render(sty.header, h)
330		}
331	
332		rows := make([][]string, 0, len(tokens))
333		for _, t := range tokens {
334			rows = append(rows, []string{
335				sty.render(sty.id, t.ID),
336				styleName(sty, t.Name),
337				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
338				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
339				styleLastUsed(sty, t.LastUsedAt, now),
340				styleExpires(sty, t.ExpiresAt, now),
341			})
342		}
343	
344		widths := make([]int, len(headerCells))
345		for i, h := range header {
346			widths[i] = lipgloss.Width(h)
347		}
348		for _, row := range rows {
349			for i, c := range row {
350				if cw := lipgloss.Width(c); cw > widths[i] {
351					widths[i] = cw
352				}
353			}
354		}
355	
356		writeRow(w, header, widths)
357		for _, row := range rows {
358			writeRow(w, row, widths)
359		}
360	}
361	
362	func writeRow(w io.Writer, cells []string, widths []int) {
363		for i, c := range cells {
364			fmt.Fprint(w, c)
365			if i < len(cells)-1 {
366				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
367			}
368		}
369		fmt.Fprintln(w)
370	}
371	
372	func styleName(sty authListStyles, name string) string {
373		if name == "" {
374			return sty.render(sty.dim, placeholderDash)
375		}
376		return sty.render(sty.name, name)
377	}
378	
379	func styleLastUsed(sty authListStyles, lastUsed *string, now time.Time) string {
380		if lastUsed == nil {
381			return sty.render(sty.dim, lastUsedNever)
382		}
383		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
384	}
385	
386	func styleExpires(sty authListStyles, expiresAt string, now time.Time) string {
387		formatted := formatAuthDate(expiresAt)
388		switch classifyExpiresAt(expiresAt, now) {
389		case expiresExpired:
390			return sty.render(sty.expired, formatted)
391		case expiresSoon:
392			return sty.render(sty.warning, formatted)
393		case expiresNormal:
394			return sty.render(sty.value, formatted)
395		}
396		return sty.render(sty.value, formatted)
397	}
398	
399	func lastUsedSortKey(t api.Token) string {
400		if t.LastUsedAt == nil {
401			return ""
402		}
403		return *t.LastUsedAt
404	}
405	
406	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
407	func formatAuthDate(s string) string {
408		if s == "" {
409			return placeholderDash
410		}
411		if ts, err := time.Parse(time.RFC3339, s); err == nil {
412			return ts.Local().Format("2006-01-02")
413		}
414		return s
415	}
416	
417	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
418	// and absolute-date branches that the shared formatRelativeDuration helper
419	// doesn't cover.
420	func formatAuthLastUsed(s *string, now time.Time) string {
421		if s == nil || *s == "" {
422			return lastUsedNever
423		}
424		ts, err := time.Parse(time.RFC3339, *s)
425		if err != nil {
426			return *s
427		}
428		delta := now.Sub(ts)
429		switch {
430		case delta < 0, delta >= 30*24*time.Hour:
431			return ts.Local().Format("2006-01-02")
432		case delta >= 24*time.Hour && delta < 48*time.Hour:
433			return "yesterday"
434		default:
435			return formatRelativeDuration(delta)
436		}
437	}
438	
439	type expiresState int
440	
441	const (
442		expiresNormal expiresState = iota
443		expiresSoon
444		expiresExpired
445	)
446	
447	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
448	// color the EXPIRES column so tokens worth rotating stand out.
449	func classifyExpiresAt(s string, now time.Time) expiresState {
450		if s == "" {
451			return expiresNormal
452		}
453		ts, err := time.Parse(time.RFC3339, s)
454		if err != nil {
455			return expiresNormal
456		}
457		delta := ts.Sub(now)
458		switch {
459		case delta <= 0:
460			return expiresExpired
461		case delta < 7*24*time.Hour:
462			return expiresSoon
463		default:
464			return expiresNormal
465		}
466	}
467	
468	func fallback(s, alt string) string {
469		if strings.TrimSpace(s) == "" {
470			return alt
471		}
472		return s
473	}
474	
475	// --- revoke -----------------------------------------------------------------
476	
477	func newAuthRevokeCmd() *cobra.Command {
478		var revokeCurrent bool
479		var insecureHTTPAuth bool
480		cmd := &cobra.Command{
481			Use:   "revoke [id]",
482			Short: "Revoke an API token by id",
483			Long:  "Revoke a specific API token. Use --current to revoke the token used by this CLI (equivalent to 'entire logout').",
484			Args:  cobra.MaximumNArgs(1),
485			RunE: func(cmd *cobra.Command, args []string) error {
486				id := ""
487				if len(args) == 1 {
488					id = args[0]
489				}
490				if id == "" && !revokeCurrent {
491					return cmd.Help()
492				}
493				if id != "" && revokeCurrent {
494					return errors.New("cannot use both <id> and --current")
495				}
496				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
497					return err
498				}
499				return runAuthRevoke(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
500					auth.NewContextStore(), defaultListTokens, defaultRevokeTokenByID, defaultRevokeCurrentToken,
501					auth.RemoveCurrentContext, api.AuthBaseURL(), id, revokeCurrent)
502			},
503		}
504		cmd.Flags().BoolVar(&revokeCurrent, "current", false, "Revoke the token used by this CLI and remove the local copy")
505		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
506		return cmd
507	}
508	
509	func defaultRevokeTokenByID(ctx context.Context, id string) error {
510		token, err := resolveDataAPIToken(ctx)
511		if err != nil {
512			return err
513		}
514		return newAPITokensClient(token).RevokeToken(ctx, id) //nolint:wrapcheck // RevokeToken already wraps with action context
515	}
516	
517	func runAuthRevoke(
518		ctx context.Context,
519		outW, errW io.Writer,
520		store tokenStore,
521		list authTokenLister,
522		revokeByID authTokenRevoker,
523		revokeCurrent revokeCurrentFunc,
524		clearContext clearContextFunc,
525		baseURL, id string,
526		current bool,
527	) error {
528		token, err := store.GetToken(baseURL)
529		if err != nil {
530			return fmt.Errorf("read keychain: %w", err)
531		}
532		if token == "" {
533			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
534		}
535	
536		if current {
537			// Revoking our own token is just logout — reuse that path so behavior
538			// stays identical (best-effort revoke + local delete + context clear).
539			return runLogout(ctx, outW, errW, store, revokeCurrent, clearContext, baseURL)
540		}
541	
542		if err := revokeByID(ctx, id); err != nil {
543			return err
544		}
545	
546		// The list endpoint requires bearer auth, so a 401 here means the id we
547		// just revoked was the same one this CLI is using — the local copy is now
548		// stale and would otherwise produce confusing 401s on every command, so
549		// remove both the legacy keyring entry and the active context.
550		if _, listErr := list(ctx); listErr != nil && api.IsHTTPErrorStatus(listErr, http.StatusUnauthorized) {
551			if delErr := store.DeleteToken(baseURL); delErr != nil {
552				return fmt.Errorf("revoked token %s but failed to remove local copy: %w", id, delErr)
553			}
554			if ctxErr := clearContext(); ctxErr != nil {
555				fmt.Fprintf(errW, "Warning: revoked token %s but failed to clear current context: %v\n", id, ctxErr)
556			}
557			fmt.Fprintf(outW, "Revoked token %s (this was your local token; removed from keychain).\n", id)
558			return nil
559		}
560	
561		fmt.Fprintf(outW, "Revoked token %s.\n", id)
562		return nil
563	}
