1	package discovery
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"time"
11	
12		"github.com/gofrs/flock"
13	)
14	
15	const (
16		cacheFileName = "nodes.json"
17		lockTimeout   = 5 * time.Second
18		lockRetry     = 100 * time.Millisecond
19	
20		// DefaultTTL is the cache TTL for replica sets discovered via info/refs.
21		DefaultTTL = 24 * time.Hour
22	)
23	
24	// ClusterCache is the top-level cache structure, keyed by cluster host.
25	type ClusterCache map[string]*ClusterEntry
26	
27	// ClusterEntry holds cached data for a single cluster.
28	type ClusterEntry struct {
29		Nodes          []string              `json:"nodes"`
30		NodesExpiresAt time.Time             `json:"nodes_expires_at"`
31		Repos          map[string]*RepoEntry `json:"repos,omitempty"`
32	}
33	
34	// RepoEntry caches the hosting nodes for a single repository.
35	type RepoEntry struct {
36		Nodes     []string  `json:"nodes"`
37		ExpiresAt time.Time `json:"expires_at"`
38	}
39	
40	// DefaultCacheDir returns ~/.cache/entire, respecting XDG_CACHE_HOME.
41	func DefaultCacheDir() string {
42		if xdg := os.Getenv("XDG_CACHE_HOME"); xdg != "" {
43			return filepath.Join(xdg, "entire")
44		}
45		home, _ := os.UserHomeDir() //nolint:errcheck // best-effort default
46		return filepath.Join(home, ".cache", "entire")
47	}
48	
49	// LoadCache reads the node cache from disk. Returns an empty cache if the file
50	// does not exist. This is an unlocked read — fine for read-only callers; use
51	// ModifyCache for read-modify-write sequences.
52	func LoadCache(cacheDir string) (ClusterCache, error) {
53		return readCacheNoLock(filepath.Join(cacheDir, cacheFileName))
54	}
55	
56	// SaveCache writes the cache to disk atomically under an exclusive flock.
57	func SaveCache(cacheDir string, cache ClusterCache) error {
58		if err := os.MkdirAll(cacheDir, 0700); err != nil {
59			return fmt.Errorf("create cache dir: %w", err)
60		}
61		path := filepath.Join(cacheDir, cacheFileName)
62		unlock, err := lockCache(path)
63		if err != nil {
64			return err
65		}
66		defer unlock()
67		return writeCacheNoLock(path, cache)
68	}
69	
70	// ModifyCache atomically applies fn to the node cache under a single
71	// exclusive flock — load, mutate, and write all happen with the lock held.
72	// Use this for any read-modify-write sequence; LoadCache followed by
73	// SaveCache releases the lock between them and races concurrent writers
74	// (e.g. two parallel clone/fetch/push processes updating nodes.json), losing
75	// each other's entries.
76	func ModifyCache(cacheDir string, fn func(ClusterCache) error) error {
77		if err := os.MkdirAll(cacheDir, 0700); err != nil {
78			return fmt.Errorf("create cache dir: %w", err)
79		}
80		path := filepath.Join(cacheDir, cacheFileName)
81		unlock, err := lockCache(path)
82		if err != nil {
83			return err
84		}
85		defer unlock()
86	
87		cache, err := readCacheNoLock(path)
88		if err != nil {
89			return err
90		}
91		if err := fn(cache); err != nil {
92			return err
93		}
94		return writeCacheNoLock(path, cache)
95	}
96	
97	func lockCache(path string) (func(), error) {
98		fl := flock.New(path + ".lock")
99		ctx, cancel := context.WithTimeout(context.Background(), lockTimeout)
100		defer cancel()
101	
102		locked, err := fl.TryLockContext(ctx, lockRetry)
103		if err != nil {
104			return nil, fmt.Errorf("acquire cache lock: %w", err)
105		}
106		if !locked {
107			return nil, errors.New("timeout acquiring cache lock")
108		}
109		return func() { _ = fl.Unlock() }, nil //nolint:errcheck // unlock failure is non-fatal
110	}
