78			return fmt.Errorf("send-pack stdout pipe: %w", err)
79		}
80		if err := sp.Start(); err != nil {
81			return fmt.Errorf("starting send-pack: %w", err)
82		}
83	
84		respCh := make(chan io.Reader, 1)
85		feedErr := make(chan error, 1)
86		go func() {
87			defer spIn.Close()
88			if _, err := spIn.Write(preamble.Bytes()); err != nil {
89				feedErr <- fmt.Errorf("writing refspecs to send-pack: %w", err)
90				return
91			}
92			if _, err := spIn.Write(advertisement); err != nil {
93				feedErr <- fmt.Errorf("writing advertisement to send-pack: %w", err)
94				return
95			}
96			resp, ok := <-respCh
97			if !ok {
98				feedErr <- nil
99				return
100			}
101			if _, err := io.Copy(spIn, resp); err != nil {
102				feedErr <- fmt.Errorf("piping receive-pack response to send-pack: %w", err)
103				return
104			}
