108		spOutReader := bufio.NewReader(spOut)
109		var requestBody bytes.Buffer
110		if err := gitproto.ReadSendPackRequest(spOutReader, &requestBody); err != nil {
111			close(respCh)
112			killAndWaitSendPack(sp, "after reading send-pack request failed")
113			return fmt.Errorf("reading send-pack request: %w", err)
114		}
115		amendedBody, err := gitproto.AppendAgentToReceivePackRequest(requestBody.Bytes(), Agent)
116		if err != nil {
117			close(respCh)
118			killAndWaitSendPack(sp, "after amending receive-pack agent failed")
119			return fmt.Errorf("amending receive-pack agent: %w", err)
120		}
121	
122		resp, err := t.ServiceRPC(ctx, serviceReceivePack, bytes.NewReader(amendedBody))
123		if err != nil {
124			close(respCh)
125			killAndWaitSendPack(sp, "after posting receive-pack failed")
126			return fmt.Errorf("posting receive-pack: %w", err)
127		}
