136		// status lines that transport-helper.c:push_update_refs_status
137		// expects.
138		flushBuf := make([]byte, 4)
139		if _, err := io.ReadFull(spOutReader, flushBuf); err != nil {
140			_ = resp.Close()
141			return fmt.Errorf("reading send-pack trailing flush: %w", err)
142		}
143		if string(flushBuf) != "0000" {
