173	// readPushBatch collects the "push <src>:<dst>" lines that follow the
174	// initial firstLine (already consumed by the dispatcher), stopping at
175	// the blank line that terminates the batch.
176	func readPushBatch(firstLine string, stdin *bufio.Reader) ([]string, error) {
177		spec, ok := strings.CutPrefix(firstLine, "push ")
178		if !ok {
179			return nil, fmt.Errorf("expected 'push <src>:<dst>', got %q", firstLine)
180		}
181		refspecs := []string{spec}
182		for {
183			line, err := stdin.ReadString('\n')
184			if err != nil && err != io.EOF {
185				return nil, fmt.Errorf("reading push batch: %w", err)
186			}
187			line = strings.TrimRight(line, "\n\r")
188			if line == "" {
189				return refspecs, nil
190			}
191			spec, ok := strings.CutPrefix(line, "push ")
192			if !ok {
193				return nil, fmt.Errorf("expected 'push <src>:<dst>', got %q", line)
194			}
195			refspecs = append(refspecs, spec)
196			if err == io.EOF {
197				return refspecs, nil
198			}
199		}
200	}
