203		if sp == nil || sp.Process == nil {
204			return
205		}
206		if err := sp.Process.Kill(); err != nil && !errors.Is(err, os.ErrProcessDone) {
207			debuglog.Printf("send-pack cleanup %s: kill: %v", reason, err)
208		}
209		if err := sp.Wait(); err != nil {
210			debuglog.Printf("send-pack cleanup %s: wait: %v", reason, err)
211		}
212	}
